export declare const TRACE_CSS = "\n.nxcp-trace {\n  container-type: inline-size;\n  border: 1px solid var(--nxcp-border);\n  border-radius: var(--nxcp-radius-md, 10px);\n  background: var(--nxcp-surface-2, var(--nxcp-surface-muted));\n  overflow: hidden;\n  font-size: 12px;\n  line-height: 16px;\n}\n.nxcp-trace-toggle {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  min-width: 0;\n  padding: 8px 12px;\n  border: 0;\n  background: transparent;\n  color: var(--nxcp-text-muted);\n  font: inherit;\n  font-weight: 600;\n  text-align: start;\n  cursor: pointer;\n}\n.nxcp-trace-toggle:focus-visible,\n.nxcp-row-head:focus-visible,\n.nxcp-row-raw-toggle:focus-visible {\n  outline: 2px solid var(--nxcp-accent);\n  outline-offset: -2px;\n}\n.nxcp-trace-label {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.nxcp-trace-chip {\n  flex: none;\n  padding: 0 6px;\n  border: 1px solid var(--nxcp-border);\n  border-radius: var(--nxcp-radius-pill, 999px);\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n  font-size: 10.5px;\n  font-weight: 500;\n  line-height: 15px;\n  white-space: nowrap;\n}\n.nxcp-trace-elapsed,\n.nxcp-row-duration,\n.nxcp-agent-duration {\n  flex: none;\n  margin-inline-start: auto;\n  font-family: var(--nxcp-mono);\n  font-size: 10px;\n  font-weight: 400;\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n.nxcp-chevron {\n  flex: none;\n  width: 7px;\n  height: 7px;\n  margin-inline-start: 4px;\n  border-inline-end: 1.5px solid currentColor;\n  border-bottom: 1.5px solid currentColor;\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n  transform: rotate(45deg) translateY(-2px);\n  transition: transform var(--nxcp-motion-fast, 120ms ease-out);\n}\n/* The header label fills the row, so the elapsed figure needs no auto margin of its own. */\n.nxcp-trace-elapsed { margin-inline-start: 0; }\n[aria-expanded='true'] > .nxcp-chevron { transform: rotate(-135deg) translateY(-1px); }\n.nxcp-trace-body {\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n  padding: 9px 12px;\n  border-top: 1px solid var(--nxcp-border);\n}\n/* Author display rules beat the UA's [hidden], so the collapse must be restated here. */\n.nxcp-trace-body[hidden],\n.nxcp-row-detail[hidden] { display: none; }\n.nxcp-trace-plan {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  color: var(--nxcp-text-muted);\n}\n.nxcp-trace-plan-label {\n  font-size: 10.5px;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n}\n.nxcp-trace-plan-reasoning { margin: 0; overflow-wrap: anywhere; }\n.nxcp-trace-plan-lines {\n  margin: 0;\n  padding-inline-start: 18px;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n.nxcp-trace-nodes {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n  gap: 7px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n@container (min-width: 560px) {\n  .nxcp-trace-nodes { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .nxcp-trace-node[data-kind='tool'] { grid-column: 1 / -1; }\n  .nxcp-agent .nxcp-trace-nodes { grid-template-columns: minmax(0, 1fr); }\n}\n.nxcp-row { min-width: 0; }\n.nxcp-row-head {\n  display: flex;\n  align-items: flex-start;\n  gap: 9px;\n  width: 100%;\n  min-width: 0;\n  margin: 0;\n  padding: 2px 4px;\n  border: 0;\n  border-radius: var(--nxcp-radius-sm, 6px);\n  background: transparent;\n  color: var(--nxcp-text-muted);\n  font: inherit;\n  text-align: start;\n}\nbutton.nxcp-row-head { cursor: pointer; }\nbutton.nxcp-row-head:hover { background: var(--nxcp-surface-3, var(--nxcp-surface-muted)); }\n.nxcp-row-head > .nxcp-glyph { margin-top: 2px; }\n.nxcp-row-label { flex: none; max-width: 60%; overflow-wrap: anywhere; }\n.nxcp-row-args {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-family: var(--nxcp-mono);\n  font-size: 10.5px;\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n}\n.nxcp-row-expires {\n  flex: none;\n  color: var(--nxcp-warning);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n.nxcp-row[data-status='running'] > .nxcp-row-head {\n  animation: nxcp-trace-pulse 1.6s ease-in-out infinite;\n}\n.nxcp-row[data-status='awaiting_approval'] > .nxcp-row-head {\n  background: color-mix(in srgb, var(--nxcp-warning) 12%, transparent);\n  color: var(--nxcp-text);\n}\n.nxcp-row-detail {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-inline-start: 24px;\n  padding: 4px 0 2px;\n  color: var(--nxcp-text-muted);\n}\n.nxcp-row-detail-text { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; }\n.nxcp-row-raw-toggle {\n  align-self: flex-start;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--nxcp-accent);\n  font: inherit;\n  font-size: 11px;\n  cursor: pointer;\n}\n.nxcp-row-raw {\n  max-height: 240px;\n  margin: 0;\n  padding: 8px;\n  overflow: auto;\n  border-radius: var(--nxcp-radius-sm, 6px);\n  background: var(--nxcp-surface-3, var(--nxcp-surface-muted));\n  font-family: var(--nxcp-mono);\n  font-size: 11px;\n  line-height: 1.45;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n.nxcp-row > .nxcp-trace-nodes { margin-inline-start: 20px; margin-top: 4px; }\n.nxcp-agent {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  min-width: 0;\n  padding: 8px 10px;\n  border: 1px solid var(--nxcp-border);\n  border-inline-start: 3px solid var(--nxcp-accent);\n  border-radius: var(--nxcp-radius-md, 10px);\n  background: var(--nxcp-surface);\n}\n.nxcp-agent[data-domain='cafm'] { border-inline-start-color: var(--nxcp-domain-cafm, #0f766e); }\n.nxcp-agent-head {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  min-width: 0;\n}\n.nxcp-agent-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-weight: 700;\n  color: var(--nxcp-text);\n}\n.nxcp-agent-domain {\n  flex: none;\n  font-size: 10.5px;\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n}\n.nxcp-agent-task {\n  margin: 0;\n  font-style: italic;\n  color: var(--nxcp-text-muted);\n  overflow-wrap: anywhere;\n}\n.nxcp-agent-feedback { margin: 0; color: var(--nxcp-text-muted); overflow-wrap: anywhere; }\n.nxcp-agent-feedback strong { color: var(--nxcp-text); }\n.nxcp-glyph {\n  position: relative;\n  flex: none;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--nxcp-text-tertiary, var(--nxcp-text-muted));\n}\n.nxcp-glyph svg { display: block; width: 100%; height: 100%; }\n.nxcp-glyph[data-glyph='tick'] { color: var(--nxcp-success); }\n.nxcp-glyph[data-glyph='cross'] { color: var(--nxcp-danger); }\n.nxcp-glyph[data-glyph='shield'] { color: var(--nxcp-warning); }\n.nxcp-glyph[data-glyph='ring'] {\n  border: 2px solid var(--nxcp-accent);\n  border-top-color: transparent;\n  border-radius: 50%;\n  box-sizing: border-box;\n  animation: nxcp-spin 0.8s linear infinite;\n}\n.nxcp-glyph[data-glyph='dots'] { gap: 4px; }\n.nxcp-glyph-dot {\n  width: 5px;\n  height: 5px;\n  border-radius: 50%;\n  background: currentColor;\n  animation: nxcp-dot 1s infinite;\n}\n.nxcp-glyph-dot:nth-child(2) { animation-delay: 0.2s; }\n.nxcp-glyph-dot:nth-child(3) { animation-delay: 0.4s; }\n.nxcp-glyph-stop {\n  width: 70%;\n  height: 70%;\n  border-radius: 2px;\n  background: currentColor;\n}\n.nxcp-trace-toggle > .nxcp-glyph[data-glyph='tick'] { color: var(--nxcp-text-tertiary, var(--nxcp-text-muted)); }\n@keyframes nxcp-spin {\n  to { transform: rotate(360deg); }\n}\n@keyframes nxcp-dot {\n  0%, 80%, 100% { opacity: 0.25; }\n  40% { opacity: 1; }\n}\n@keyframes nxcp-trace-pulse {\n  50% { opacity: 0.55; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .nxcp-glyph[data-glyph='ring'],\n  .nxcp-glyph-dot,\n  .nxcp-row[data-status='running'] > .nxcp-row-head { animation: none; }\n  .nxcp-chevron { transition: none; }\n}\n";
